def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Complete single-cell gaps in horizontal runs. When the two sides
    # differ, continue the color from the right-hand side.
    for r in range(h):
        for c in range(1, w - 1):
            if g[r][c] == 0 and g[r][c - 1] != 0 and g[r][c + 1] != 0:
                g[r][c] = g[r][c - 1] if g[r][c - 1] == g[r][c + 1] else g[r][c + 1]

    # Extend bottom-origin vertical lines upward to the first horizontal
    # line that they meet, leaving that horizontal line intact.
    for c in range(w):
        occupied = [r for r in range(h) if grid[r][c] != 0]
        if not occupied:
            continue
        start = max(occupied)
        color = grid[start][c]

        # Only treat a run reaching the bottom portion as a vertical marker.
        if start < h - 4:
            continue
        top = start
        while top > 0 and grid[top - 1][c] == color:
            top -= 1

        r = top - 1
        while r >= 0 and g[r][c] == 0:
            g[r][c] = color
            r -= 1

    return g
