def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    for c in range(w):
        # The vertical marker is the same-colored run reaching the bottom.
        marker_color = grid[h - 1][c]
        if marker_color == 0:
            continue
        marker_start = h - 1
        while marker_start > 0 and grid[marker_start - 1][c] == marker_color:
            marker_start -= 1

        # Locate horizontal bars crossing this column, including a one-cell gap.
        crossings = []
        for r in range(h):
            if r >= marker_start:
                continue
            left = grid[r][c - 1] if c > 0 else 0
            here = grid[r][c]
            right = grid[r][c + 1] if c + 1 < w else 0

            has_bar = any(
                grid[r][j] != 0 and grid[r][j + 1] == grid[r][j]
                for j in range(w - 1)
            )
            if not has_bar:
                continue

            if here != 0:
                crossings.append((r, here))
            elif left != 0 and left == right:
                crossings.append((r, left))

        if not crossings:
            continue

        # Each crossing's color fills upward from the previous crossing;
        # the bottom marker color fills below the last crossing.
        for i, (r, color) in enumerate(crossings):
            start = crossings[i - 1][0] + 1 if i > 0 else 0
            for rr in range(start, r + 1):
                out[rr][c] = color

        for rr in range(crossings[-1][0] + 1, h):
            out[rr][c] = marker_color

    return out
